"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["76970"],{97458(e){e.exports=JSON.parse('{"id":"V4-190","slug":"sovereign-wealth-fund","term":"Sovereign Wealth Fund","also_known_as":[],"difficulty":"Intermediate","definition":"A sovereign wealth fund is a state-owned investment fund that invests a country\u2019s surplus money, such as revenue from natural resources or foreign currency reserves, in assets around the world.","explanation":["Sovereign wealth funds are typically created by countries with large surpluses, often from oil, gas or mineral exports, or from trade surpluses. Their goals can include saving wealth for future generations, stabilising the government\u2019s budget when commodity prices fall and supporting national economic development.","Sovereign wealth funds invest in a wide range of assets, including shares, bonds, property, infrastructure and private equity, often internationally to diversify away from the domestic economy.","The largest include Norway\u2019s Government Pension Fund Global, built from oil and gas revenues and worth well over a trillion US dollars, and large funds in China, the United Arab Emirates, Saudi Arabia, Kuwait, Qatar and Singapore.","For example, Norway\u2019s fund owns small stakes in thousands of companies worldwide, and the government can withdraw only a limited share of its value each year to fund the budget.","Sovereign wealth funds can be powerful investors and sometimes raise concerns about political influence over foreign companies. The Santiago Principles, agreed in 2008, set voluntary standards for their governance, transparency and investment practices."],"note":"","total":1725,"prev":{"slug":"sovereign-default","term":"Sovereign Default"},"next":{"slug":"special-dividend","term":"Special Dividend"}}')}}]);